import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice with single line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-003');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[0].qty, 2);
  assert.ok(r.value.lines[0].name);
  assert.ok(typeof r.value.lines[0].unitPrice === 'number');
  assert.ok(typeof r.value.lines[0].vatRate === 'number');
});

test('createInvoice creates a valid invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].sku, 'DES-HOUR');
});

test('createInvoice reports an unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports an invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '10/07/2026',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports a non-existent date', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-02-30',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports an invalid date string', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: 'not-a-date',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports an empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports invalid qty (not an integer)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid qty (zero)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports invalid qty (negative)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports an unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const lines = [{ sku: 'LOGO-PACK', qty: 2 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, linesCopy);
});

test('createInvoice copies product data from catalogue', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const line = r.value.lines[0];
  assert.ok(line.name.length > 0);
  assert.ok(Number.isInteger(line.unitPrice));
  assert.ok(typeof line.vatRate === 'number');
  assert.ok(line.vatRate >= 0 && line.vatRate <= 100);
});

test('lineTotal multiplies qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 2000 }), 10000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 100 }), 1000);
});

test('lineTotal rounds fractional cents', () => {
  assert.equal(lineTotal({ qty: 3, unitPrice: 333 }), 999);
  assert.equal(lineTotal({ qty: 2, unitPrice: 0.7 }), 1);
});

test('invoiceTotals sums line totals for subtotal', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  const expectedSubtotal = 2 * 8500 + 1 * 120000;
  assert.equal(totals.subtotal, expectedSubtotal);
  // DES-HOUR: 17000 * 21% = 3570, LOGO-PACK: 120000 * 21% = 25200, VAT total: 28770
  assert.equal(totals.vat, 28770);
  assert.equal(totals.total, 165770);
});

test('invoiceTotals includes VAT in total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'ICON-SET', qty: 5, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, discountPercent: 0 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // ICON-SET: 4900 * 21% = 1029, STICKER: 5000 * 21% = 1050, VAT: 2079
  assert.equal(totals.subtotal, 9900);
  assert.equal(totals.vat, 2079);
  assert.equal(totals.total, 11979);
});

test('invoiceTotals returns zero for empty-lines invoice if created', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with single line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 3, discountPercent: 0 }],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  // BRAND-BOOK: 735000 * 9% = 66150
  assert.equal(totals.subtotal, 3 * 245000);
  assert.equal(totals.vat, 66150);
  assert.equal(totals.total, 801150);
});

test('addLine adds a new SKU to the invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[1].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[1].qty, 2);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = addLine(invoice, { sku: 'LOGO-PACK', qty: 2 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[0].qty, 3);
});

test('addLine validates qty', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: -1 }), { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU exists', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(addLine(invoice, { sku: 'UNKNOWN-SKU', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = { ...r.value, status: 'sent' };

  assert.deepEqual(addLine(invoice, { sku: 'DES-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const originalLength = invoice.lines.length;

  addLine(invoice, { sku: 'DES-HOUR', qty: 2 });

  assert.equal(invoice.lines.length, originalLength);
});

test('removeLine removes a line by SKU', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = removeLine(invoice, 'LOGO-PACK');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('removeLine reports LINE_NOT_FOUND if SKU not on invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(removeLine(invoice, 'UNKNOWN-SKU'), { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  assert.deepEqual(removeLine(invoice, 'LOGO-PACK'), { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = { ...r.value, status: 'sent' };

  assert.deepEqual(removeLine(invoice, 'LOGO-PACK'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const originalLength = invoice.lines.length;

  removeLine(invoice, 'LOGO-PACK');

  assert.equal(invoice.lines.length, originalLength);
});

test('issueInvoice assigns an invoice number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.ok, true);
  assert.ok(r2.value.number);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-003');
  assert.equal(r2.value.issueDate, '2026-10-07');
  assert.equal(r2.value.lines.length, 1);
});

test('issueInvoice uses the next available number based on existing numbers', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r2 = issueInvoice(invoice, existing);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0003');
});

test('issueInvoice refuses to issue a non-draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = { ...r.value, status: 'issued' };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  assert.equal(invoice.status, 'draft');
  assert.ok(!invoice.number);

  issueInvoice(invoice, []);

  assert.equal(invoice.status, 'draft');
  assert.ok(!invoice.number);
});

test('createInvoice accepts discountPercent and stores it', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice defaults discountPercent to tier discount if not provided', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier, 2.5% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice rejects invalid discountPercent (out of range)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 101 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects invalid discountPercent (negative)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice rejects invalid discountPercent (not a number)', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 'ten' }],
  });
  assert.deepEqual(r, { ok: false, error: 'DISCOUNT_INVALID' });
});

test('createInvoice accepts decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('lineDiscount calculates discount for a line', () => {
  const line = { qty: 2, unitPrice: 10000, discountPercent: 10 };
  const discount = lineDiscount(line);
  assert.equal(discount, 2000); // 2 * 10000 = 20000, 20000 * 10% = 2000
});

test('lineDiscount defaults to 0 if discountPercent not provided', () => {
  const line = { qty: 2, unitPrice: 10000 };
  const discount = lineDiscount(line);
  assert.equal(discount, 0);
});

test('lineDiscount handles decimal discountPercent', () => {
  const line = { qty: 1, unitPrice: 10000, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  assert.equal(discount, 1250); // 10000 * 12.5% = 1250
});

