  const invoice = r.value;

  const r2 = renderInvoiceText(invoice);
  assert.equal(r2.ok, true);
  const text = r2.value;
  // Subtotal: 137000, Discount: 3425, Taxable: 133575, VAT: 28051, Total: 161626
